from pathlib import Path
r=Path('E:/OpenLeague')
s='''//! Original C9A0B9 encoded default handlers followed by actual CABDE8 resolver.
use std::collections::{BTreeMap,BTreeSet};use crate::{audio_bus_bank::Error,audio_plugin_factory::Memory};use crate::audio_path_source_virtual_cleanup::put;
pub trait Services:crate::audio_crt_windows_dispatch_resolver::Services{fn encode_pointer(&mut self,value:u32,m:&mut BTreeMap<u32,Memory>,dead:&mut BTreeSet<u32>)->Result<u32,Error>;}
pub fn initialize(m:&mut BTreeMap<u32,Memory>,d:&mut BTreeSet<u32>,s:&mut impl Services)->Result<u32,Error>{let nil=s.encode_pointer(0,m,d)?;for a in[0x14ae620,0x14ae624,0x14ae86c,0x14ae60c,0x14ae610,0x14ae614,0x14ae618]{put(m,d,a,4,nil)?;}let terminate=s.encode_pointer(0xc98c0a,m,d)?;put(m,d,0x14ae5b0,4,terminate)?;put(m,d,0x14af108,4,nil)?;crate::audio_crt_windows_dispatch_resolver::resolve(m,d,s)}
#[cfg(test)]mod tests{
 use super::*;use serde_json::{Value,json};
 fn bytes(s:&str)->Vec<u8>{(0..s.len()).step_by(2).map(|i|u8::from_str_radix(&s[i..i+2],16).unwrap()).collect()}
 struct Api{regions:Vec<(String,u32,usize)>,calls:Vec<Value>,module:u32,layout:String,index:u32,key:u32}
 impl Api{fn snapshot(&self,m:&BTreeMap<u32,Memory>)->Value{let mut out=json!({});for(n,r,z)in &self.regions{out[n]=json!((0..*z).map(|j|format!("{:02x}",crate::audio_path_memory::read(m,r+j as u32,1).unwrap()[0])).collect::<String>());}out}fn call(&mut self,mut v:Value,m:&BTreeMap<u32,Memory>){v["at_call"]=self.snapshot(m);self.calls.push(v);}}
 impl crate::audio_crt_windows_dispatch_resolver::Services for Api{fn module_handle(&mut self,name:&str,m:&mut BTreeMap<u32,Memory>,_:&mut BTreeSet<u32>)->Result<u32,Error>{self.call(json!({"kind":"GetModuleHandleW","name":name,"result":self.module}),m);Ok(self.module)}fn procedure_address(&mut self,module:u32,name:&str,m:&mut BTreeMap<u32,Memory>,_:&mut BTreeSet<u32>)->Result<u32,Error>{let r=if self.module!=0&&self.layout=="all"{0x40004000+self.index*16}else{0};self.call(json!({"kind":"GetProcAddress","module":module,"name":name,"result":r}),m);self.index+=1;Ok(r)}}
 impl Services for Api{fn encode_pointer(&mut self,value:u32,m:&mut BTreeMap<u32,Memory>,_:&mut BTreeSet<u32>)->Result<u32,Error>{let result=value^self.key;self.call(json!({"kind":"EncodePointer","input":value,"result":result}),m);Ok(result)}}
 #[test]fn audio_crt_global_dispatch_initialization_matches72_original_encoded_null_static_terminate_pointer_default_handlers_real33_export_resolver_and_all_entry_banks(){let p:Value=serde_json::from_str(&crate::audio_test_fixture("data/4.20/audio_crt_global_dispatch_initialization_preparation.json")).unwrap();assert_eq!(p["passed"],true);assert_eq!(p["case_count"],72);
 for(i,row)in p["cases"].as_array().unwrap().iter().enumerate(){let regions=p["regions"].as_array().unwrap().iter().map(|v|(v["name"].as_str().unwrap().to_owned(),v["reference"].as_u64().unwrap()as u32,v["size"].as_u64().unwrap()as usize)).collect::<Vec<_>>();let mut m=regions.iter().map(|(n,r,_)|(*r,Memory{reference:*r,raw:bytes(row["before"][n].as_str().unwrap())})).collect();let mut d=BTreeSet::new();let mut api=Api{regions,calls:vec![],module:row["module"].as_u64().unwrap()as u32,layout:row["layout"].as_str().unwrap().into(),index:0,key:row["encode_null"].as_u64().unwrap()as u32};let result=initialize(&mut m,&mut d,&mut api).unwrap();assert_eq!(result as u64,row["result"].as_u64().unwrap(),"native EAX residue {i}");assert_eq!(json!(api.calls),row["calls"],"encoded defaults and every resolver intermediate entry bank {i}");assert_eq!(api.snapshot(&m),row["after"],"all canonical globals {i}");assert_eq!(api.index,33);assert!(d.is_empty());}}
}
''';(r/'crates/core/src/audio_crt_global_dispatch_initialization.rs').write_text(s,encoding='utf-8')
s='''//! Actual CABC85/CABCA3 TLS/FLS allocation and release wrappers.
use std::collections::{BTreeMap,BTreeSet};use crate::{audio_bus_bank::Error,audio_plugin_factory::Memory};use crate::audio_path_source_virtual_cleanup::get;
pub trait Services{fn allocate_slot(&mut self,function:u32,callback:Option<u32>,m:&mut BTreeMap<u32,Memory>,dead:&mut BTreeSet<u32>)->Result<u32,Error>;fn free_slot(&mut self,function:u32,index:u32,m:&mut BTreeMap<u32,Memory>,dead:&mut BTreeSet<u32>)->Result<u32,Error>;}
pub fn allocate(m:&mut BTreeMap<u32,Memory>,d:&mut BTreeSet<u32>,callback:u32,s:&mut impl Services)->Result<u32,Error>{let function=get(m,d,0x2da5300,4)?^get(m,d,0x1222ed0,4)?;s.allocate_slot(function,if function==0{None}else{Some(callback)},m,d)}
pub fn free(m:&mut BTreeMap<u32,Memory>,d:&mut BTreeSet<u32>,index:u32,s:&mut impl Services)->Result<u32,Error>{let function=get(m,d,0x2da5304,4)?^get(m,d,0x1222ed0,4)?;s.free_slot(function,index,m,d)}
#[cfg(test)]mod tests{
 use super::*;use serde_json::{Value,json};
 fn bytes(s:&str)->Vec<u8>{(0..s.len()).step_by(2).map(|i|u8::from_str_radix(&s[i..i+2],16).unwrap()).collect()}
 struct Api{regions:Vec<(String,u32,usize)>,calls:Vec<Value>,result:u32}
 impl Api{fn snapshot(&self,m:&BTreeMap<u32,Memory>)->Value{let mut out=json!({});for(n,r,z)in &self.regions{out[n]=json!((0..*z).map(|j|format!("{:02x}",crate::audio_path_memory::read(m,r+j as u32,1).unwrap()[0])).collect::<String>());}out}}
 impl Services for Api{fn allocate_slot(&mut self,function:u32,callback:Option<u32>,m:&mut BTreeMap<u32,Memory>,_:&mut BTreeSet<u32>)->Result<u32,Error>{assert_eq!(function,if callback.is_some(){0x40028020}else{0});self.calls.push(json!({"kind":if callback.is_some(){"FlsAlloc"}else{"TlsAlloc"},"arguments":callback.into_iter().collect::<Vec<_>>(),"result":self.result,"at_call":self.snapshot(m)}));Ok(self.result)}fn free_slot(&mut self,function:u32,index:u32,m:&mut BTreeMap<u32,Memory>,_:&mut BTreeSet<u32>)->Result<u32,Error>{assert!(function==0||function==0x40028030);self.calls.push(json!({"kind":if function==0{"TlsFree"}else{"FlsFree"},"arguments":[index],"result":self.result,"at_call":self.snapshot(m)}));Ok(self.result)}}
 #[test]fn audio_crt_tls_slot_wrappers_matches72_original_tls_fls_cookie_dispatch_callback_drop_or_forward_raw_returns_and_canonical_banks(){let p:Value=serde_json::from_str(&crate::audio_test_fixture("data/4.20/audio_crt_tls_slot_wrappers_preparation.json")).unwrap();assert_eq!(p["passed"],true);assert_eq!(p["case_count"],72);
 for(i,row)in p["cases"].as_array().unwrap().iter().enumerate(){let regions=p["regions"].as_array().unwrap().iter().map(|v|(v["name"].as_str().unwrap().to_owned(),v["reference"].as_u64().unwrap()as u32,v["size"].as_u64().unwrap()as usize)).collect::<Vec<_>>();let mut m=regions.iter().map(|(n,r,_)|(*r,Memory{reference:*r,raw:bytes(row["before"][n].as_str().unwrap())})).collect();let mut d=BTreeSet::new();let mut api=Api{regions,calls:vec![],result:row["api_result"].as_u64().unwrap()as u32};let parameter=row["parameter"].as_u64().unwrap()as u32;let result=if row["action"]=="allocate"{allocate(&mut m,&mut d,parameter,&mut api)}else{free(&mut m,&mut d,parameter,&mut api)}.unwrap();assert_eq!(result as u64,row["result"].as_u64().unwrap(),"raw native slot/BOOL {i}");assert_eq!(json!(api.calls),row["calls"],"original TLS/FLS import arguments and bank {i}");assert_eq!(api.snapshot(&m),row["after"],"unchanged canonical globals {i}");assert_eq!(row["stack_delta"],4,"original wrapper caller retains cdecl argument {i}");assert!(d.is_empty());}}
}
''';(r/'crates/core/src/audio_crt_tls_slot_wrappers.rs').write_text(s,encoding='utf-8');p=r/'crates/core/src/lib.rs';s=p.read_text(encoding='utf-8');assert 'pub mod audio_crt_global_dispatch_initialization;'not in s;p.write_text(s+'\npub mod audio_crt_global_dispatch_initialization;\npub mod audio_crt_tls_slot_wrappers;\n',encoding='utf-8');(r/'tools/implement_audio_crt_global_dispatch_tls_slots.py').write_text(Path(__file__).read_text(encoding='utf-8'),encoding='utf-8');print('Implemented original global handlers+resolver and TLS/FLS slot wrappers;72+72 native comparisons')
